mapper.select:
SELECT * FROM (
SELECT RES.*, AHP.BUSINESS_STATUS_, AHP.BUSINESS_KEY_, ARP.NAME_ AS processDefinitionName, ARP.KEY_ AS processDefinitionKey, ARP.VERSION_ AS processDefinitionVersion, ter.create_by, ter.create_time AS applyTime, us.user_name AS userName FROM ACT_RU_TASK RES INNER JOIN ACT_HI_PROCINST AHP ON RES.PROC_INST_ID_ = AHP.PROC_INST_ID_ INNER JOIN ACT_RE_PROCDEF ARP ON ARP.ID_ = RES.PROC_DEF_ID_ INNER JOIN test_expense_reimbursement ter ON AHP.BUSINESS_KEY_ = ter.id INNER JOIN sys_user us ON ter.create_by = us.user_id WHERE RES.PARENT_TASK_ID_ IS NULL
UNION ALL SELECT HTI.*, AHP.BUSINESS_STATUS_, AHP.BUSINESS_KEY_, ARP.NAME_ AS processDefinitionName, ARP.KEY_ AS processDefinitionKey, ARP.VERSION_ AS processDefinitionVersion, ter.create_by, ter.create_time AS applyTime, us.user_name AS userName FROM ACT_HI_TASKINST HTI INNER JOIN ACT_HI_PROCINST AHP ON HTI.PROC_INST_ID_ = AHP.PROC_INST_ID_ INNER JOIN ACT_RE_PROCDEF ARP ON ARP.ID_ = HTI.PROC_DEF_ID_ INNER JOIN test_expense_reimbursement ter ON AHP.BUSINESS_KEY_ = ter.id INNER JOIN sys_user us ON ter.create_by = us.user_id WHERE HTI.PARENT_TASK_ID_ IS NULL AND HTI.END_TIME_ IS NOT NULL
UNION ALL SELECT AHT.*, AHP.BUSINESS_STATUS_, AHP.BUSINESS_KEY_, ARP.NAME_ AS processDefinitionName, ARP.KEY_ AS processDefinitionKey, ARP.VERSION_ AS processDefinitionVersion, ter.create_by, ter.create_time AS applyTime, us.user_name AS userName FROM ACT_HI_TASKINST AHT INNER JOIN ACT_HI_PROCINST AHP ON AHT.PROC_INST_ID_ = AHP.PROC_INST_ID_ INNER JOIN ACT_RE_PROCDEF ARP ON ARP.ID_ = AHT.PROC_DEF_ID_ INNER JOIN test_expense_reimbursement ter ON AHP.BUSINESS_KEY_ = ter.id INNER JOIN sys_user us ON ter.create_by = us.user_id WHERE AHT.PARENT_TASK_ID_ IS NOT NULL AND AHT.scope_type_ = 'copy'
) AS t ${ew.getCustomSqlSegment}
